PACKAGE BODY pack_histo_crr AS
/******************************************************************************
   Nom :    pack_histo_crr (body)
   But :    Historisation des donnees provenant de BTR et des donnees envoyees
            sur 7 ans glissants (2 ans + 5 ans)
   Date :   10/09/2008
   Auteur : A. Guilmart
   Modification :
******************************************************************************/


------------------------------------------------------
-- nom : procedure p_histo_ident_syndication           --
-- but : historisation de la table ident_syndication   --
-- auteur : CDS ATOS (LFD) - 12/11/2018 				--
-- ANACREDIT US 552              								--
------------------------------------------------------

PROCEDURE p_histo_ident_syndication IS
    l_position varchar2(20);

BEGIN
    --rejeu
    DELETE CRR_2A.HIS_ident_syndication WHERE DT_ARRETE = g_dt_arrete;
    COMMIT;

    -- purge de la table d'historique 5 ans
    l_position := 'purge 5 ans';
    DELETE FROM CRR_10A.HIS_ident_syndication WHERE DT_ARRETE < add_months(g_dt_arrete, -g_nb_mois_purge_7ans);
    COMMIT;

    -- historisation de l'arrete en cours
    l_position := 'histo 2 ans';
    INSERT INTO CRR_2A.HIS_ident_syndication (
        ID_OPERATION,
		CD_SYS_INT,
		CD_SOC_JURI,
		LIB_SOC_JURI,
		CD_POSITION_ENTITE_RISQUE,
		REF_SYNDICATION
		,DT_ARRETE -- 17/12/2018 - CDS ATOS (LFD) - ANACREDIT US 570
)
    SELECT  ID_OPERATION,
		CD_SYS_INT,
		CD_SOC_JURI,
		LIB_SOC_JURI,
		CD_POSITION_ENTITE_RISQUE,
		REF_SYNDICATION
		,DT_ARRETE -- 17/12/2018 - CDS ATOS (LFD) - ANACREDIT US 570
    FROM CRR.ident_syndication;
    COMMIT;

    -- historisation de l'arrete sur 5 ans
    l_position := 'histo 5 ans';
    INSERT INTO CRR_10A.HIS_ident_syndication (
       ID_OPERATION,
		CD_SYS_INT,
		CD_SOC_JURI,
		LIB_SOC_JURI,
		CD_POSITION_ENTITE_RISQUE,
		REF_SYNDICATION
		,DT_ARRETE -- 17/12/2018 - CDS ATOS (LFD) - ANACREDIT US 570
		)
    SELECT  ID_OPERATION,
		CD_SYS_INT,
		CD_SOC_JURI,
		LIB_SOC_JURI,
		CD_POSITION_ENTITE_RISQUE,
		REF_SYNDICATION
		,DT_ARRETE -- 17/12/2018 - CDS ATOS (LFD) - ANACREDIT US 570
    FROM CRR_2A.his_ident_syndication SY
    WHERE  DT_ARRETE < add_months(g_dt_arrete, -g_nb_mois_purge_2ans);
    COMMIT;

    -- purge de la table d'historique 2 ans
    l_position := 'purge 2 ans';
    DELETE FROM CRR_2A.HIS_ident_syndication SY WHERE DT_ARRETE < add_months(g_dt_arrete, -g_nb_mois_purge_2ans);
    COMMIT; 

EXCEPTION
    WHEN OTHERS THEN
             ROLLBACK;
              pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'proc p_histo_ident_syndication:'||l_position,50074);
END p_histo_ident_syndication;




