	--CDS_ATOS (MNE) : 12/01/2021 : Rework de l'alimentation des champs ID_OPERATION_ORI et FLAG_AVENANT
	--Reprise du cheminement du oneshoot de reprise de stock pour CRR_10A.his_btr_operation
	MERGE INTO CRR_2A.his_btr_operation HIS
	USING (SELECT  	ope.dt_arrete,ope.id_operation,ope.cd_sys_int,ope.id_tiers
					,CASE   WHEN ope.ID_operation like 'D%' THEN substr(ope.id_operation,1,length(ope.id_operation)-2)
							ELSE substr(ope.id_operation,1,length(ope.id_operation)-4)
					END ID_OPERATION_ORI
			FROM  CRR_2A.HIS_BTR_OPERATION      ope
			WHERE cd_sys_int = 'KSP'
		  ) MAJ
	ON ( HIS.dt_arrete=MAJ.dt_arrete and HIS.ID_OPERATION = MAJ.ID_OPERATION and HIS.CD_SYS_INT = MAJ.CD_SYS_INT and HIS.ID_TIERS = MAJ.ID_TIERS)
	WHEN MATCHED THEN UPDATE SET  HIS.ID_OPERATION_ORI = MAJ.ID_OPERATION_ORI WHERE CD_SYS_INT = 'KSP';

	UPDATE CRR_2A.HIS_BTR_OPERATION SET FLAG_AVENANT='O' WHERE cd_sys_int = 'KSP';

	UPDATE CRR_2A.HIS_BTR_OPERATION OPE SET FLAG_AVENANT='N' WHERE NOT EXISTS ( SELECT 1
																				  FROM CRR_2A.HIS_BTR_OPERATION OPE2
																				  WHERE OPE2.ID_OPERATION_ORI = OPE.ID_OPERATION_ORI
																				  AND OPE2.ID_OPERATION != OPE.ID_OPERATION
																				  AND OPE2.DT_ARRETE = OPE.DT_ARRETE
																				  AND OPE2.CD_SYS_INT = 'KSP')
															   and OPE.CD_SYS_INT = 'KSP';

	MERGE INTO CRR_2A.his_btr_operation HIS
	USING CRR_2A.TRANSCO_ID_OPE_ORI ORI     
	ON ( HIS.ID_OPERATION = ORI.ID_OPERATION)
	WHEN MATCHED THEN UPDATE SET  HIS.ID_OPERATION_ORI = ORI.ID_OPERATION_ORI,FLAG_AVENANT='O' WHERE CD_SYS_INT = 'KSP';
	COMMIT;
