    WHERE DT_ARRETE < add_months(g_dt_arrete, -g_nb_mois_purge_2ans);
    COMMIT;

    -- purge de la table d'historique 2 ans
    l_position := 'purge 2 ans';
    DELETE FROM CRR_2A.HIS_PROVISIONS_AFFECTEES WHERE DT_ARRETE < add_months(g_dt_arrete, -g_nb_mois_purge_2ans);
    COMMIT;
    DELETE FROM CRR_2A.HIS_PROVISIONS_DECOTES_P9 WHERE DT_ARRETE < add_months(g_dt_arrete, -g_nb_mois_purge_2ans);
    COMMIT;
    DELETE FROM CRR_2A.HIS_PROVISIONS_DETAIL_P8 WHERE DT_ARRETE < add_months(g_dt_arrete, -g_nb_mois_purge_2ans);
    COMMIT;
    DELETE FROM CRR_2A.HIS_PROVISIONS_AGREG_P8 WHERE DT_ARRETE < add_months(g_dt_arrete, -g_nb_mois_purge_2ans);
    COMMIT;

EXCEPTION
    WHEN OTHERS THEN
             ROLLBACK;
              pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'proc p_histo_provisions_affectees:'||l_position,50074);
END p_histo_provisions_affectees;

