-- nom : procedure p_histo_rs_ape_naf               --
-- but : historisation de la table RS_APE_NAF       --
-- auteur : L. Blanchard, le 27/11/2008             --
-- entree : /                                       --
-- retour : /                                       --
------------------------------------------------------
PROCEDURE p_histo_rs_ape_naf IS
    l_position varchar2(20);
    DT_ARRETE DATE;

BEGIN
    DT_ARRETE := g_dt_arrete;

    L_POSITION := 'SI REJEU';

    DELETE HIS_RS_APE_NAF WHERE DT_DEBUT_VALIDITE = LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1;
    UPDATE HIS_RS_APE_NAF SET DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1)
        WHERE DT_FIN_VALIDITE = DT_ARRETE;

    L_POSITION := 'INSERT';

    -- INSERT DANS L HISTO SI LA VALEUR EST ABSENTE SUR LE MOIS PRECEDENT UNIQUEMENT
    -- PERMET D HISTORISER MEME SI ON REVIENT A UNE ANCIENNE VALEUR
    INSERT INTO HIS_RS_APE_NAF (CD_APE, LIB_ACTIVITE, DT_DEBUT_VALIDITE, DT_FIN_VALIDITE)
    SELECT CD_APE, LIB_ACTIVITE,
        LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1, DT_ARRETE FROM RS_APE_NAF
    WHERE NOT EXISTS (SELECT 1 FROM HIS_RS_APE_NAF HIS_RS
                WHERE HIS_RS.CD_APE = RS_APE_NAF.CD_APE
                    AND HIS_RS.LIB_ACTIVITE = RS_APE_NAF.LIB_ACTIVITE
                    AND HIS_RS.DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1));

    L_POSITION := 'UPDATE';

    -- ON UPDATE UNIQUEMENT LES VALEURS ACTUELLES SUR LE DERNIER HISTORIQUE
    -- SI ON REVIENT A UNE ANCIENNE VALEUR, L ANCIENNE VALEUR N EST PAS UPDATEE
    -- SI UNE VALEUR N EST PLUS PRESENTE, ON NE CHANGE PAS SA DATE
    UPDATE HIS_RS_APE_NAF SET DT_FIN_VALIDITE = DT_ARRETE
    WHERE EXISTS (SELECT 1 FROM RS_APE_NAF
            WHERE HIS_RS_APE_NAF.CD_APE = RS_APE_NAF.CD_APE
            AND HIS_RS_APE_NAF.LIB_ACTIVITE = RS_APE_NAF.LIB_ACTIVITE)
    AND HIS_RS_APE_NAF.DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1);

    COMMIT;

EXCEPTION
    WHEN OTHERS THEN
             ROLLBACK;
              pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'proc p_histo_rs_ape_naf:'||l_position,50074);
END p_histo_rs_ape_naf;

