            AND nvl(HIS_RS_CATEG_CPT.N_MOIS_SUP_REVENTE,0) = nvl(RS_CATEG_CPT.N_MOIS_SUP_REVENTE,0))
    AND HIS_RS_CATEG_CPT.DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1);

