---------------------------------------------------------
-- nom : procedure p_histo_RS_STATUT_RISQ_OPE          --
-- but : historisation de la table RS_STATUT_RISQ_OPE  --
-- auteur : L. Blanchard, le 27/11/2008                --
-- entree : NA                                         --
-- retour : NA                                         --
---------------------------------------------------------
PROCEDURE p_histo_RS_STATUT_RISQ_OPE IS
    l_position varchar2(20);
    DT_ARRETE DATE;

BEGIN
    DT_ARRETE  := g_dt_arrete;
    L_POSITION := 'SI REJEU';

    DELETE HIS_RS_STATUT_RISQ_OPE WHERE DT_DEBUT_VALIDITE = LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1;
    UPDATE HIS_RS_STATUT_RISQ_OPE SET DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1)
    WHERE DT_FIN_VALIDITE = DT_ARRETE;

    -- INSERT DANS L HISTO SI LA VALEUR EST ABSENTE SUR LE MOIS PRECEDENT UNIQUEMENT
    -- PERMET D HISTORISER MEME SI ON REVIENT A UNE ANCIENNE VALEUR
    --DEBUT :: KLx_Risques (BAL) :: M63356/65088: ajout de la colonne FLAG_OPE_RESIL
    L_POSITION := 'INSERT';

    INSERT 
    INTO HIS_RS_STATUT_RISQ_OPE (CD_STATUT_RISQ_OPE, LIBELLE, PRIORITE, CD_SRA_PATRIC, MAX_PERIODE, DT_DEBUT_VALIDITE, DT_FIN_VALIDITE, FLAG_OPE_RESIL)
    SELECT  
         CD_STATUT_RISQ_OPE
        ,LIBELLE
        ,PRIORITE
        ,CD_SRA_PATRIC
        ,MAX_PERIODE
        ,LAST_DAY(ADD_MONTHS(DT_ARRETE, -1)) + 1
        ,DT_ARRETE
        ,FLAG_OPE_RESIL 
    FROM RS_STATUT_RISQ_OPE
    WHERE NOT EXISTS (SELECT 1 
                      FROM HIS_RS_STATUT_RISQ_OPE HIS_RS
                      WHERE HIS_RS.CD_STATUT_RISQ_OPE = RS_STATUT_RISQ_OPE.CD_STATUT_RISQ_OPE
                        AND HIS_RS.LIBELLE            = RS_STATUT_RISQ_OPE.LIBELLE
                        AND HIS_RS.PRIORITE           = RS_STATUT_RISQ_OPE.PRIORITE
                        AND HIS_RS.CD_SRA_PATRIC      = RS_STATUT_RISQ_OPE.CD_SRA_PATRIC
                        -- Pour egaliter de NULL. Si les deux sont null alors egaux
                        -- Si les deux ne sont pas null alors les valeurs doivent aï¿½tre les memes
                        AND  ( ( HIS_RS.MAX_PERIODE IS NOT NULL AND RS_STATUT_RISQ_OPE.MAX_PERIODE IS NOT NULL 
                                    AND HIS_RS.MAX_PERIODE    = RS_STATUT_RISQ_OPE.MAX_PERIODE
                                ) OR ( HIS_RS.MAX_PERIODE IS NULL AND RS_STATUT_RISQ_OPE.MAX_PERIODE IS NULL )
                            )
                        AND HIS_RS.FLAG_OPE_RESIL     = RS_STATUT_RISQ_OPE.FLAG_OPE_RESIL
                        AND HIS_RS.DT_FIN_VALIDITE    = ADD_MONTHS(DT_ARRETE, -1));
    --FIN :: KLx_Risques (BAL) :: M63356/65088: ajout de la colonne FLAG_OPE_RESIL

    -- ON UPDATE UNIQUEMENT LES VALEURS ACTUELLES SUR LE DERNIER HISTORIQUE
    -- SI ON REVIENT A UNE ANCIENNE VALEUR, L ANCIENNE VALEUR N EST PAS UPDATEE
    -- SI UNE VALEUR N EST PLUS PRESENTE, ON NE CHANGE PAS SA DATE
    L_POSITION := 'UPDATE';
    UPDATE HIS_RS_STATUT_RISQ_OPE SET DT_FIN_VALIDITE = DT_ARRETE
    WHERE EXISTS (SELECT 1 FROM RS_STATUT_RISQ_OPE
            WHERE HIS_RS_STATUT_RISQ_OPE.CD_STATUT_RISQ_OPE = RS_STATUT_RISQ_OPE.CD_STATUT_RISQ_OPE
            AND HIS_RS_STATUT_RISQ_OPE.LIBELLE = RS_STATUT_RISQ_OPE.LIBELLE
            AND HIS_RS_STATUT_RISQ_OPE.PRIORITE = RS_STATUT_RISQ_OPE.PRIORITE
            AND HIS_RS_STATUT_RISQ_OPE.CD_SRA_PATRIC = RS_STATUT_RISQ_OPE.CD_SRA_PATRIC
            AND ( ( HIS_RS_STATUT_RISQ_OPE.MAX_PERIODE IS NOT NULL AND RS_STATUT_RISQ_OPE.MAX_PERIODE IS NOT NULL 
                    AND HIS_RS_STATUT_RISQ_OPE.MAX_PERIODE    = RS_STATUT_RISQ_OPE.MAX_PERIODE
                ) OR ( HIS_RS_STATUT_RISQ_OPE.MAX_PERIODE IS NULL AND RS_STATUT_RISQ_OPE.MAX_PERIODE IS NULL )
            )
            AND HIS_RS_STATUT_RISQ_OPE.FLAG_OPE_RESIL  = RS_STATUT_RISQ_OPE.FLAG_OPE_RESIL)
    AND HIS_RS_STATUT_RISQ_OPE.DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1);
    COMMIT;

EXCEPTION WHEN OTHERS THEN
    ROLLBACK;
    pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'proc p_histo_RS_STATUT_RISQ_OPE:'||l_position,50074);
END p_histo_RS_STATUT_RISQ_OPE;

