    -----------------------------------------------------------------
    -- nom : procedure p_his_RS_CORR_METHODE_NOTATION              --
    -- but : historisation de la table RS_CORRES_METHODE_NOTATION  --
    -- auteur : KLX RISQUE  19/07/2022                             --
    -- entree : /                                                  --
    -- retour : /                                                  --
    -- KLX RISQUE - Mantis 62593 - RS_CORRES_METHODE_NOTATION      --
    -----------------------------------------------------------------
    PROCEDURE p_his_RS_CORR_METHODE_NOTATION IS
        v_etape varchar2(30);
        DT_ARRETE DATE;

    BEGIN
        DT_ARRETE := g_dt_arrete;

        v_etape := 'Effacage si REJEU';
        -- Efface les donnï¿½es marquer au premier de mois
        DELETE HIS_RS_CORR_METHODE_NOTATION WHERE DT_DEBUT_VALIDITE = LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1;
        -- Marque toutes les donnï¿½es  comme ï¿½tant valident jusqu'a la date de l'arrete antï¿½rieur si marquer a la date actuelle
        UPDATE HIS_RS_CORR_METHODE_NOTATION 
            SET DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1)
        WHERE DT_FIN_VALIDITE = DT_ARRETE;

        v_etape := 'INSERT les nouvelles lignes';

        -- INSERT DANS L HISTO SI LA VALEUR EST ABSENTE SUR LE MOIS PRECEDENT UNIQUEMENT
        -- PERMET D HISTORISER MEME SI ON REVIENT A UNE ANCIENNE VALEUR
        INSERT INTO HIS_RS_CORR_METHODE_NOTATION (CD_METHODE_NOTATION, TYPE_DE_METHODOLOGIE, DT_DEBUT_VALIDITE, DT_FIN_VALIDITE)
        SELECT CD_METHODE_NOTATION ,
                TYPE_DE_METHODOLOGIE,
                LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1, -- Dï¿½but validitï¿½ = dï¿½but du mois d'arrete
                DT_ARRETE
        FROM RS_CORRES_METHODE_NOTATION rs
        WHERE NOT EXISTS (  SELECT 1 FROM HIS_RS_CORR_METHODE_NOTATION his_rs -- Si on a pas la mï¿½me ligne au mois dernier alors on historise
                            WHERE his_rs.CD_METHODE_NOTATION        = rs.CD_METHODE_NOTATION
                                AND his_rs.TYPE_DE_METHODOLOGIE     = rs.TYPE_DE_METHODOLOGIE
                                AND his_rs.DT_FIN_VALIDITE          = ADD_MONTHS(DT_ARRETE, -1)
                        );
        -- ADD_MONTHS(DT_ARRETE, -1) => Si la DT_ARRETE est le dernier jour du mois, ADD_MONTHS(DT_ARRETE, -1) donnera le dernier jour du mois antï¿½rieur
        v_etape := 'UPDATE';

        -- ON UPDATE UNIQUEMENT LES VALEURS ACTUELLES SUR LE DERNIER HISTORIQUE
        -- SI ON REVIENT A UNE ANCIENNE VALEUR, L ANCIENNE VALEUR N EST PAS UPDATEE
        -- SI UNE VALEUR N EST PLUS PRESENTE, ON NE CHANGE PAS SA DATE
        UPDATE HIS_RS_CORR_METHODE_NOTATION his_rs
        SET DT_FIN_VALIDITE = DT_ARRETE
        WHERE EXISTS (  SELECT 1 FROM RS_CORRES_METHODE_NOTATION rs
                        WHERE his_rs.CD_METHODE_NOTATION  = rs.CD_METHODE_NOTATION
                            AND his_rs.TYPE_DE_METHODOLOGIE = rs.TYPE_DE_METHODOLOGIE
                        )
        AND his_rs.DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1);

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'proc p_his_RS_CORR_METHODE_NOTATION:'||v_etape,50074);
    END p_his_RS_CORR_METHODE_NOTATION;

-- =================================================================================
-- 	procedure      : p_histo_RS_ORIG_VALO_ACT_CBI
--  description    : historisation de la table RS_ORIG_VALO_ACT_CBI
--	auteur		   : Bruno Almeida (KLx_Risques)
--  params. entree : NA
--  params. retour : NA
--  date creation  : 11/04/2023
--  dern. modif.   : dd/mm/yyyy
--  historique     : Project VTR CBI :: sous-chapitre 4.1.4 du SFG 
-- =================================================================================
    PROCEDURE p_histo_RS_ORIG_VALO_ACT_CBI IS
        --variables locales
        L_POSITION varchar2(20);
        DT_ARRETE  date;
    BEGIN
        DT_ARRETE := g_dt_arrete;

        L_POSITION := 'SI REJEU';
        DELETE HIS_RS_ORIG_VALO_ACT_CBI 
         WHERE DT_DEBUT_VALIDITE = LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1;

        UPDATE HIS_RS_ORIG_VALO_ACT_CBI 
           SET DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1)
         WHERE DT_FIN_VALIDITE = DT_ARRETE;

        L_POSITION := 'INSERT';
        -- INSERT DANS L HISTO SI LA VALEUR EST ABSENTE SUR LE MOIS PRECEDENT UNIQUEMENT
        -- PERMET D HISTORISER MEME SI ON REVIENT A UNE ANCIENNE VALEUR
        INSERT 
          INTO HIS_RS_ORIG_VALO_ACT_CBI (CD_ORIGINE_VALORISATION
                                        ,LIB_ORIGINE_VALORISATION
                                        ,CD_METHODO_VALORISATION --AFR 08/08/12 lot BTR 6.3 : Ajout des provisions dans CRR
                                        ,FLAG_EXPERT
                                        ,TYPE_CALCUL
                                        ,DT_DEBUT_VALIDITE
                                        ,DT_FIN_VALIDITE)
        SELECT CD_ORIGINE_VALORISATION
             , LIB_ORIGINE_VALORISATION
             , CD_METHODO_VALORISATION --AFR 08/08/12 lot BTR 6.3 : Ajout des provisions dans CRR 
             , FLAG_EXPERT
             , TYPE_CALCUL
             , LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1
             , DT_ARRETE
          FROM RS_ORIG_VALO_ACT_CBI rs
         WHERE NOT EXISTS (SELECT 1 FROM HIS_RS_ORIG_VALO_ACT_CBI his_rs
                            WHERE his_rs.CD_ORIGINE_VALORISATION           = rs.CD_ORIGINE_VALORISATION
                              AND his_rs.LIB_ORIGINE_VALORISATION          = rs.LIB_ORIGINE_VALORISATION
                              AND nvl(his_rs.CD_METHODO_VALORISATION,'9')  = nvl(rs.CD_METHODO_VALORISATION,'9') --AFR 08/08/12 lot BTR 6.3 : Ajout des provisions dans CRR 
                              AND nvl(his_rs.FLAG_EXPERT,'X')              = nvl(rs.FLAG_EXPERT,'X')
                              AND nvl(his_rs.TYPE_CALCUL,'NA')             = nvl(rs.TYPE_CALCUL,'NA')
                              AND his_rs.DT_FIN_VALIDITE                   = ADD_MONTHS(DT_ARRETE, -1));

        L_POSITION := 'UPDATE';
        -- ON UPDATE UNIQUEMENT LES VALEURS ACTUELLES SUR LE DERNIER HISTORIQUE
        -- SI ON REVIENT A UNE ANCIENNE VALEUR, L ANCIENNE VALEUR N EST PAS UPDATEE
        -- SI UNE VALEUR N EST PLUS PRESENTE, ON NE CHANGE PAS SA DATE
        UPDATE HIS_RS_ORIG_VALO_ACT_CBI his_rs
           SET DT_FIN_VALIDITE = DT_ARRETE
         WHERE EXISTS (SELECT 1 FROM RS_ORIG_VALO_ACT_CBI rs
                        WHERE his_rs.CD_ORIGINE_VALORISATION           = rs.CD_ORIGINE_VALORISATION
                          AND his_rs.LIB_ORIGINE_VALORISATION          = rs.LIB_ORIGINE_VALORISATION
                          AND nvl(his_rs.CD_METHODO_VALORISATION,'9')  = nvl(rs.CD_METHODO_VALORISATION,'9')
                          AND nvl(his_rs.FLAG_EXPERT,'X')              = nvl(rs.FLAG_EXPERT,'X')
                          AND nvl(his_rs.TYPE_CALCUL,'NA')             = nvl(rs.TYPE_CALCUL,'NA'))
           AND his_rs.DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1);
        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
        ROLLBACK;
        pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'proc p_histo_rs_orig_valo_act_cbi:'||l_position,50074);
    END p_histo_RS_ORIG_VALO_ACT_CBI;
