                    AND his_rs.CD_INSEE_COMMUNE = rs.CD_INSEE_COMMUNE
                    AND his_rs.INDIC_PARTICUL_DISTRIBUTION = rs.INDIC_PARTICUL_DISTRIBUTION
                    AND his_rs.INDIC_BUREAU_DISTRIBUTEUR = rs.INDIC_BUREAU_DISTRIBUTEUR
