BEGIN
    DT_ARRETE := g_dt_arrete;

    L_POSITION := 'SI REJEU';

    DELETE HIS_COMPL_CRE_ANADEFI WHERE DT_DEBUT_VALIDITE = LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1;

    UPDATE HIS_COMPL_CRE_ANADEFI SET DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1)
    WHERE DT_FIN_VALIDITE = DT_ARRETE;

