          CD_METHODO_NOTE       ,
          NOTE_INTERNE_GRPE     ,
          DT_NOTE_INTERNE_GRPE  ,
          CD_GRILLE_NOTE        ,
          MNT_CA                                ,
          DUREE_CA_GRPE                    ,
          NATURE_CA_GRPE                ,
          DUREE_EXERCICE_GRPE   ,
