  DELETE
  FROM CRR_2A.HIS_RS_CORRES_SOC_JURI_UCABAIL
  WHERE DT_ARRETE = g_dt_arrete;
  COMMIT;
  -- purge de la table d'historique 5 ans
  l_position := 'purge 5 ans';
  DELETE
  FROM CRR_10A.HIS_RS_CORRES_SOC_JURI_UCABAIL
  WHERE DT_ARRETE < add_months(g_dt_arrete, -g_nb_mois_purge_7ans);
