-- nom : procedure p_histo_RS_FLAG_DEFAUT           --
-- but : historisation de la table RS_FLAG_DEFAUT   --
-- auteur : CDS ATOS, le 14/06/2016                 --
-- Projet Bale 2 D.faut et restructuration          --
-- entr.e : /                                       --
-- retour : /                                       --
------------------------------------------------------
PROCEDURE p_histo_RS_FLAG_DEFAUT IS
    l_position varchar2(20);
    DT_ARRETE DATE;

BEGIN
    DT_ARRETE := g_dt_arrete;

    L_POSITION := 'SI REJEU';

    DELETE HIS_RS_FLAG_DEFAUT  WHERE DT_DEBUT_VALIDITE = LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1;
    UPDATE HIS_RS_FLAG_DEFAUT  SET DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1)
        WHERE DT_FIN_VALIDITE = DT_ARRETE;

    L_POSITION := 'INSERT';

    -- INSERT DANS L HISTO SI LA VALEUR EST ABSENTE SUR LE MOIS PRECEDENT UNIQUEMENT
    -- PERMET D HISTORISER MEME SI ON REVIENT A UNE ANCIENNE VALEUR
    INSERT INTO HIS_RS_FLAG_DEFAUT  (
        CD_FLAG_DEFAUT, LIBELLE_FLAG_DEFAUT, DT_DEBUT_VALIDITE, DT_FIN_VALIDITE)
    SELECT CD_FLAG_DEFAUT, LIBELLE_FLAG_DEFAUT, LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1, DT_ARRETE
        FROM RS_FLAG_DEFAUT
    WHERE NOT EXISTS (SELECT 1 FROM HIS_RS_FLAG_DEFAUT HIS_RS
                WHERE HIS_RS.CD_FLAG_DEFAUT = RS_FLAG_DEFAUT.CD_FLAG_DEFAUT
                    AND HIS_RS.LIBELLE_FLAG_DEFAUT = RS_FLAG_DEFAUT.LIBELLE_FLAG_DEFAUT
                    AND HIS_RS.DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1));

    L_POSITION := 'UPDATE';

    -- ON UPDATE UNIQUEMENT LES VALEURS ACTUELLES SUR LE DERNIER HISTORIQUE
    -- SI ON REVIENT A UNE ANCIENNE VALEUR, L ANCIENNE VALEUR N EST PAS UPDATEE
    -- SI UNE VALEUR N EST PLUS PRESENTE, ON NE CHANGE PAS SA DATE
    UPDATE HIS_RS_FLAG_DEFAUT SET DT_FIN_VALIDITE = DT_ARRETE
    WHERE EXISTS (SELECT 1 FROM RS_FLAG_DEFAUT
            WHERE HIS_RS_FLAG_DEFAUT.CD_FLAG_DEFAUT = RS_FLAG_DEFAUT.CD_FLAG_DEFAUT
            AND HIS_RS_FLAG_DEFAUT.LIBELLE_FLAG_DEFAUT = RS_FLAG_DEFAUT.LIBELLE_FLAG_DEFAUT
            )
    AND HIS_RS_FLAG_DEFAUT.DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1);

    COMMIT;

EXCEPTION
    WHEN OTHERS THEN
             ROLLBACK;
              pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'proc p_histo_RS_FLAG_DEFAUT:'||l_position,50074);
END p_histo_RS_FLAG_DEFAUT;

