	dt_arrete_bucket date; -- 17/11/2020 - CDS ATOS (LFD) - Mantis 54420

BEGIN

	-- 17/11/2020 - CDS ATOS (LFD) - Mantis 54420 
	SELECT DISTINCT DT_ARRETE INTO DT_ARRETE_ANNEXE FROM CRR.ANNEXE_IFRS;
	SELECT DISTINCT DT_ARRETE INTO DT_ARRETE_BUCKET FROM CRR.BUCKET_IFRS;
	-- FIN LFD

    --rejeu
	-- 17/11/2020 - CDS ATOS (LFD) - Mantis 54420
	DELETE FROM CRR_2A.HIS_ANNEXE_IFRS WHERE DT_ARRETE = DT_ARRETE_ANNEXE;
	COMMIT;
	DELETE FROM CRR_2A.HIS_BUCKET_IFRS WHERE DT_ARRETE = DT_ARRETE_BUCKET;
	COMMIT;
