    --delete CRR_10A.HIS_ENG_ENCOURS_CORPORATE where DT_ARRETE = add_months(g_dt_arrete, -g_nb_mois_purge_2ans-1);
    --commit;

    -- purge de la table d'historique 5 ans
    l_position := 'purge 5 ans';

    DELETE FROM CRR_10A.HIS_ANNEXE_IFRS WHERE DT_ARRETE < add_months(g_dt_arrete, -g_nb_mois_purge_7ans);
    COMMIT;
    DELETE FROM CRR_10A.HIS_BUCKET_IFRS WHERE DT_ARRETE < add_months(g_dt_arrete, -g_nb_mois_purge_7ans);
    COMMIT;

    -- historisation de l'arrete en cours
    l_position := 'histo 2 ans';

