from CRR_2A.HIS_CREDIT_P3
WHERE DT_ARRETE < add_months(g_dt_arrete, -g_nb_mois_purge_2ans);

    if sql%found then
       dbg_lignemaj :=  sql%rowcount; --M51565
    end if;

    COMMIT;
EXCEPTION --M51565 -->
 WHEN DUP_VAL_ON_INDEX THEN NULL; -- Dans le cas de doublons : on evite plantage mais on fait rien (null), on n'insere rien
   dbms_output.put_line('Doublons dans CRR_10A.HIS_CREDIT_P3 ' );
   dbg_lignemaj :=  0;  -- rien insere   
END;  --M51565 <--
dbms_output.put_line(l_position || ' INSERT CRR_10A.HIS_CREDIT_P3 ='|| dbg_lignemaj ); --M51565

	   -- purge de la table d'historique 2 ans
    l_position := 'purge 2 ans';
    DELETE FROM CRR_2A.HIS_CREDIT_P3 WHERE DT_ARRETE < add_months(g_dt_arrete, -g_nb_mois_purge_2ans);
    if sql%found then
       dbms_output.put_line(l_position || ' DELETE CRR_2A.HIS_CREDIT_P3 ='|| sql%rowcount ); --M51565
    end if;
    COMMIT;

EXCEPTION
    WHEN OTHERS THEN
             ROLLBACK;
              pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'proc p_histo_CREDIT_P3:'||l_position,50074);
END p_histo_CREDIT_P3;


