    ,PCCO_INTERET -- US49-RL2022 KLx-GHU
	FROM CRR.REF_COMPTA_ARPSON ;
	COMMIT;
-- historisation de l'arrete sur 5 ans
  l_position := 'histo 5 ans';
	INSERT
	INTO CRR_10A.HIS_REF_COMPTA_ARPSON
	( 
	DT_ARRETE, 
	FAMILLE, 
	INSTRUMENT, 
	REGRP_CPTA, 
	INTRAGROUPE, 
	CODE_DEVISE, 
	PCEC_MISE_EN_PLACE, 
	PCEC_INTERET
    ,PCCO_MISE_EN_PLACE -- US49-RL2022 KLx-GHU
    ,PCCO_INTERET -- US49-RL2022 KLx-GHU
	)
