	CD_CONSO_CPT,
	TYPE_ENREGISTREMENT,
	ID_SURETE,
	ID_ENGAGEMENT,
	A_EXTRAIRE 
	from CRR.LIENS_M3P3
    ;
    COMMIT;


INSERT INTO CRR_10A.HIS_LIENS_M3P3
(		DT_ARRETE,
	CD_CONSO_CPT,
	TYPE_ENREGISTREMENT,
	ID_SURETE,
	ID_ENGAGEMENT,
	A_EXTRAIRE 
      )
select 
		DT_ARRETE,
	CD_CONSO_CPT,
	TYPE_ENREGISTREMENT,
	ID_SURETE,
	ID_ENGAGEMENT,
	A_EXTRAIRE   
		from CRR_2A.HIS_LIENS_M3P3
     WHERE DT_ARRETE < add_months(g_dt_arrete, -g_nb_mois_purge_2ans);
    COMMIT;

	   -- purge de la table d'historique 2 ans
    l_position := 'purge 2 ans';
    DELETE FROM CRR_2A.HIS_LIENS_M3P3 WHERE DT_ARRETE < add_months(g_dt_arrete, -g_nb_mois_purge_2ans);
    COMMIT;

EXCEPTION
    WHEN OTHERS THEN
             ROLLBACK;
              pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'proc p_histo_LIENS_M3P3:'||l_position,50074);
END p_histo_LIENS_M3P3;
