-- nom : procedure p_histo_RS_CORRES_NOTE_PD               --
-- but : historisation de la table RS_CORRES_NOTE_PD    --
-- auteur : CPD 20/01/2021                                    --
-- projet : IRBA Leasing                                                 --
----------------------------------------------------------------
PROCEDURE p_histo_RS_CORRES_NOTE_PD IS
    l_position varchar2(20);
    DT_ARRETE DATE;

BEGIN
    DT_ARRETE := g_dt_arrete;

    L_POSITION := 'SI REJEU';

    DELETE HIS_RS_CORRES_NOTE_PD WHERE DT_DEBUT_VAL = LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1;

    UPDATE HIS_RS_CORRES_NOTE_PD SET DT_FIN_VAL = ADD_MONTHS(DT_ARRETE, -1)
    WHERE DT_FIN_VAL = DT_ARRETE;

    L_POSITION := 'INSERT';

    -- INSERT DANS L HISTO SI LA VALEUR EST ABSENTE SUR LE MOIS PRECEDENT UNIQUEMENT
    -- PERMET D HISTORISER MEME SI ON REVIENT A UNE ANCIENNE VALEUR
	--28/07/21 CDS_ATOS (EMM) Mantis 57385
    INSERT INTO HIS_RS_CORRES_NOTE_PD 
		(NOTE, 
		PD_AUTRES,
		PD_C1,
		PD_PIM,
		PD_LBO,
        DT_DEBUT_VAL, 
		DT_FIN_VAL)

    SELECT NOTE, 
			PD_AUTRES,
			PD_C1,
			PD_PIM,
			PD_LBO,
           LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1, 
		   DT_ARRETE
    FROM RS_CORRES_NOTE_PD np
    WHERE NOT EXISTS (SELECT 1 FROM HIS_RS_CORRES_NOTE_PD his_np
                       WHERE his_np.NOTE   = np.NOTE
                         AND his_np.PD_AUTRES = np.PD_AUTRES
						 AND his_np.PD_C1 = np.PD_C1
						 AND his_np.PD_PIM = np.PD_PIM
						 AND his_np.PD_LBO = np.PD_LBO
                         AND his_np.DT_FIN_VAL = ADD_MONTHS(DT_ARRETE, -1));

    L_POSITION := 'UPDATE';

    -- ON UPDATE UNIQUEMENT LES VALEURS ACTUELLES SUR LE DERNIER HISTORIQUE
    -- SI ON REVIENT A UNE ANCIENNE VALEUR, L ANCIENNE VALEUR N EST PAS UPDATEE
    -- SI UNE VALEUR N EST PLUS PRESENTE, ON NE CHANGE PAS SA DATE
    UPDATE HIS_RS_CORRES_NOTE_PD his_np
    SET DT_FIN_VAL = DT_ARRETE
    WHERE EXISTS (SELECT 1 FROM RS_CORRES_NOTE_PD np
                  WHERE his_np.NOTE   = np.NOTE
                    AND his_np.PD_AUTRES = np.PD_AUTRES
					AND his_np.PD_C1 = np.PD_C1
					AND his_np.PD_PIM = np.PD_PIM
					AND his_np.PD_LBO = np.PD_LBO)
    AND his_np.DT_FIN_VAL = ADD_MONTHS(DT_ARRETE, -1);
	--Fin EMM
    COMMIT;

EXCEPTION
    WHEN OTHERS THEN
      ROLLBACK;
      pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'proc p_histo_RS_CORRES_NOTE_PD:'||l_position,50074);
END p_histo_RS_CORRES_NOTE_PD;

