-- nom : procedure p_his_SIREN_EXCLUSION                                                        --
-- but : historisation de la table SIREN_EXCLUSION dans les schema CRR_2A et CRR_10A            --
-- auteur : KLX_RISQUE (VDC) 10/03/2022                                                         --
-- entree : /                                                                                   --
-- retour : /                                                                                   --
-- Creation pour la Mantis 61386 - Ajout de la table SIREN_EXCLUSION                            --
--------------------------------------------------------------------------------------------------
    PROCEDURE p_histo_SIREN_EXCLUSION IS
        l_position varchar2(35); -- Etape dans la procedure en cas d'erreur
        vDateTransition2A5A DATE := add_months(g_dt_arrete, -g_nb_mois_purge_2ans);
    BEGIN

        l_position := 'REJEU CRR_2A';
        DELETE FROM CRR_2A.HIS_SIREN_EXCLUSION WHERE DT_ARRETE = g_dt_arrete;
        COMMIT;

        -- purge de la table d'historique 5 ans des donnees vieille de plus de X mois
        l_position := 'purge CRR_10A';
        DELETE FROM CRR_10A.HIS_SIREN_EXCLUSION WHERE DT_ARRETE < add_months(g_dt_arrete, -g_nb_mois_purge_7ans);
        COMMIT;

        l_position := 'Insertion 2A';
        INSERT INTO CRR_2A.HIS_SIREN_EXCLUSION (
            DT_ARRETE,
            SIREN
        ) SELECT DT_ARRETE,
                 SIREN
        FROM CRR.SIREN_EXCLUSION;

        l_position := 'Insertion 5A';
        INSERT INTO CRR_10A.HIS_SIREN_EXCLUSION (
            DT_ARRETE,
            SIREN
        ) SELECT DT_ARRETE,
                 SIREN
        FROM CRR_2A.HIS_SIREN_EXCLUSION
        WHERE DT_ARRETE < vDateTransition2A5A;

        COMMIT;

        -- purge de la table d'historique 2 ans
        l_position := 'purge 2 ans';
        DELETE FROM CRR_2A.HIS_SIREN_EXCLUSION WHERE DT_ARRETE < vDateTransition2A5A;
        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN 
            ROLLBACK;
            pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM, 'proc p_histo_SIREN_EXCLUSION:'||l_position, 50074);
    END p_histo_SIREN_EXCLUSION;

    -- =================================================================================
    -- 	procedure      : p_histo_RS_PARA_DONNEES_CBI
    --  description    : historisation de la table RS_PARA_DONNEES_CBI
    --	auteur		   : Bruno Almeida (KLx_Risques)
    --  params. entree : NA
    --  params. retour : NA
    --  date creation  : 17/03/2022
    --  dern. modif.   : dd/mm/yyyy
    --  historique     : M65988 - Project VTR CBI
    -- =================================================================================
    procedure p_histo_RS_PARA_DONNEES_CBI is
		--variables locales
		pEtape       varchar2(250);
		pDt_Deb_Vali date;
        pDt_Fin_Vali date;
        pDern_Dt_2A  date;
        pDern_Dt_5A  date;
        pHist_Donn   int;

    begin
        --initialisation des variables
        pDt_Fin_Vali := pack_utilitaire_7ans.f_calc_dt_arrete;
        pDt_Deb_Vali := trunc(last_day(add_months(pDt_Fin_Vali, -1))) + 1;
        pDern_Dt_2A  := add_months(pDt_Fin_Vali, -g_nb_mois_purge_2ans);
        pDern_Dt_5A  := add_months(pDt_Fin_Vali, -g_nb_mois_purge_7ans);

        --rejeu pour eviter doublons
        pEtape := 'Rejeu HIS_RS_PARA_DONNEES_CBI';
        delete 
		  from CRR.his_rs_para_donnees_cbi;
        commit;

        pEtape := 'Historisation HIS_RS_PARA_DONNEES_CBI';
        insert 
        into CRR.his_rs_para_donnees_cbi 
          (cd_famille_imm
          ,surface_act_cbi
          ,cd_postal
          ,cd_type_copropriete
          ,dt_dat
          ,cd_categ_hotel
          ,n_nb_chambre
          ,n_nb_lit
          ,cd_typo_commerce
          ,cd_typo_entrepot
          ,dt_debut_validite
          ,dt_fin_validite) 
        select 
           cd_famille_imm
          ,surface_act_cbi
          ,cd_postal
          ,cd_type_copropriete
          ,dt_dat
          ,cd_categ_hotel
          ,n_nb_chambre
          ,n_nb_lit
          ,cd_typo_commerce
          ,cd_typo_entrepot
          ,pDt_Deb_Vali
          ,pDt_Fin_Vali
        from CRR.rs_para_donnees_cbi;
        commit;

        pEtape := 'Historisation HIS_RS_PARA_DONNEES_CBI :: 2 ans';
        delete 
		  from CRR_2A.his_rs_para_donnees_cbi 
		 where dt_fin_validite = pDt_Fin_Vali;

        insert into CRR_2A.his_rs_para_donnees_cbi
		select * 
		  from CRR.his_rs_para_donnees_cbi 
		 where dt_fin_validite = pDt_Fin_Vali;
		commit;

		pEtape := 'Purge des donnees HIS_RS_PARA_DONNEES_CBI :: 2 ans';
		delete 
		  from CRR_2A.his_rs_para_donnees_cbi 
		 where dt_fin_validite < pDern_Dt_2A;
		commit;

		pEtape := 'Historisation HIS_RS_PARA_DONNEES_CBI :: 5 ans';
        delete 
		  from CRR_10A.his_rs_para_donnees_cbi 
		 where dt_fin_validite = pDt_Fin_Vali;

		insert into CRR_10A.his_rs_para_donnees_cbi
		select * 
		  from CRR.his_rs_para_donnees_cbi 
		 where dt_fin_validite = pDt_Fin_Vali;
		commit;

		pEtape := 'Purge des donnees HIS_RS_PARA_DONNEES_CBI :: 5 ans';
		delete 
		  from CRR_10A.his_rs_para_donnees_cbi 
		 where dt_fin_validite >= pDern_Dt_2A 
		    or dt_fin_validite < pDern_Dt_5A;
		commit;
    exception 
    when others then
        rollback;
        pack_utilitaire_7ans.db_traite_erreur(sqlerrm, 'Procedure: p_histo_RS_PARA_DONNEES_CBI :: Etape: ' || pEtape, 50074);
    end p_histo_RS_PARA_DONNEES_CBI;
-- =================================================================================
-- 	FIN procedure : p_histo_RS_PARA_DONNEES_CBI
-- =================================================================================
--FIN MNE	

 -- BEGIN  p_histo_RS_NTURE_DURABLE_ACTIF - 1 

PROCEDURE p_histo_RS_NTURE_DURABLE_ACTIF IS
    l_position varchar2(20);
    DT_ARRETE DATE;

BEGIN
	DT_ARRETE := g_dt_arrete;

	L_POSITION := 'SI REJEU';

DELETE HIS_RS_NATURE_DURABLE_ACTIF WHERE DT_DEBUT_VALIDITE = LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1;

	UPDATE HIS_RS_NATURE_DURABLE_ACTIF SET DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1)
	WHERE DT_FIN_VALIDITE = DT_ARRETE;

	L_POSITION := 'INSERT';

	-- INSERT DANS L HISTO SI LA VALEUR EST ABSENTE SUR LE MOIS PRECEDENT UNIQUEMENT
	-- PERMET D HISTORISER MEME SI ON REVIENT A UNE ANCIENNE VALEUR
	INSERT INTO HIS_RS_NATURE_DURABLE_ACTIF (
		 CD_INDNDA
		,LIB_INDDNA_FR
		,LIB_INDDNA_EN
		,DT_DEBUT_VALIDITE
		,DT_FIN_VALIDITE
	)
	SELECT
	     CD_INDNDA
		,LIB_INDDNA_FR
		,LIB_INDDNA_EN
		,LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1
		,DT_ARRETE
    FROM RS_NATURE_DURABLE_ACTIF rs
    WHERE NOT EXISTS (SELECT 1
						FROM  HIS_RS_NATURE_DURABLE_ACTIF his_rs
						WHERE his_rs.CD_INDNDA 	= rs.CD_INDNDA
						AND   his_rs.LIB_INDDNA_FR 	= rs.LIB_INDDNA_FR
						AND   his_rs.LIB_INDDNA_EN = rs.LIB_INDDNA_EN
						AND   his_rs.DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1));

	L_POSITION := 'UPDATE';

	-- ON UPDATE UNIQUEMENT LES VALEURS ACTUELLES SUR LE DERNIER HISTORIQUE
	-- SI ON REVIENT A UNE ANCIENNE VALEUR, L ANCIENNE VALEUR N EST PAS UPDATEE
	-- SI UNE VALEUR N EST PLUS PRESENTE, ON NE CHANGE PAS SA DATE
	UPDATE HIS_RS_NATURE_DURABLE_ACTIF his_rs
	SET DT_FIN_VALIDITE = DT_ARRETE
	WHERE EXISTS (SELECT 1
					FROM  RS_NATURE_DURABLE_ACTIF rs
					WHERE his_rs.CD_INDNDA 	= rs.CD_INDNDA
					AND   his_rs.LIB_INDDNA_FR 	= rs.LIB_INDDNA_FR
					AND    his_rs.LIB_INDDNA_EN = rs.LIB_INDDNA_EN)
	AND his_rs.DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1);

	COMMIT;

EXCEPTION
	WHEN OTHERS THEN
		ROLLBACK;
			pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'p_histo_RS_NTURE_DURABLE_ACTIF:'||l_position,50074);

END p_histo_RS_NTURE_DURABLE_ACTIF;

