-- nom : procedure p_HIS_BTR_OPE_PARTENAIRE_POOL                                                    --
-- but : historisation de la table BTR_OPE_PARTENAIRE_POOL dans les schema CRR_2A et CRR_10A        --
-- auteur : KLX_RISQUE (VDC) 02/08/2022                                                             --
-- entree : /                                                                                       --
-- retour : /                                                                                       --
-- Creation pour la Mantis 62593 - Ajout de la table BTR_OPE_PARTENAIRE_POOL, Projet LTBCE          --
------------------------------------------------------------------------------------------------------
    PROCEDURE p_HIS_BTR_OPE_PARTENAIRE_POOL IS
        l_position varchar2(35); -- Etape dans la procedure en cas d'erreur
        vDateTransition2A5A DATE := add_months(g_dt_arrete, -g_nb_mois_purge_2ans);
        vPurge5A DATE := add_months(g_dt_arrete, -g_nb_mois_purge_7ans);
    BEGIN
        l_position := 'REJEU CRR_2A';
        -- Le mieux pour le rejeu c'est faire a partir de BTR_OPE_PARTENAIRE_POOL
        --DELETE FROM CRR_2A.HIS_BTR_OPE_PARTENAIRE_POOL WHERE DT_ARRETE = g_dt_arrete;
        DELETE FROM CRR_2A.HIS_BTR_OPE_PARTENAIRE_POOL
            WHERE DT_ARRETE  = ( SELECT MAX( DT_ARRETE ) FROM CRR.BTR_OPE_PARTENAIRE_POOL );
        if sql%found then 
            dbms_output.put_line('rejeu DELETE CRR_2A.HIS_BTR_OPE_PARTENAIRE_POOL ='|| sql%rowcount ); 
        end if;
        
        -- Purge pour rejeu ( pas simple )
        l_position := 'REJEU CRR_10A';
        DELETE FROM CRR_10A.HIS_BTR_OPE_PARTENAIRE_POOL 
            WHERE DT_ARRETE = ( select min( dt_arrete ) from CRR_2A.HIS_BTR_OPE_PARTENAIRE_POOL ); 
        --COMMIT;
        if sql%found then 
            dbms_output.put_line('Rejeu DELETE CRR_10A.HIS_BTR_OPE_PARTENAIRE_POOL ='|| sql%rowcount ); 
        end if;

        l_position := 'Insertion 2A';
        INSERT INTO CRR_2A.HIS_BTR_OPE_PARTENAIRE_POOL (
            DT_ARRETE,             
            ID_PARTENAIRE_POOL,    
            CD_SYS_INT,            
            ID_OPERATION,          
            ID_TYPE_POOL,          
            QUOTE_PART_POOL,       
            MNT_VIVANT_FINANCMT,   
            FLAG_CHEF_POOL,        
            SEQ_ID_PARTENAIRE_POOL,
            SEQ_ID_TYPE_POOL,      
            TOP_ENG  
        ) SELECT DT_ARRETE,             
            ID_PARTENAIRE_POOL,    
            CD_SYS_INT,            
            ID_OPERATION,          
            ID_TYPE_POOL,          
            QUOTE_PART_POOL,       
            MNT_VIVANT_FINANCMT,   
            FLAG_CHEF_POOL,        
            SEQ_ID_PARTENAIRE_POOL,
            SEQ_ID_TYPE_POOL,      
            TOP_ENG
        FROM CRR.BTR_OPE_PARTENAIRE_POOL;

        l_position := 'Insertion 5A';
        INSERT INTO CRR_10A.HIS_BTR_OPE_PARTENAIRE_POOL (
            DT_ARRETE,             
            ID_PARTENAIRE_POOL,    
            CD_SYS_INT,            
            ID_OPERATION,          
            ID_TYPE_POOL,          
            QUOTE_PART_POOL,       
            MNT_VIVANT_FINANCMT,   
            FLAG_CHEF_POOL,        
            SEQ_ID_PARTENAIRE_POOL,
            SEQ_ID_TYPE_POOL,      
            TOP_ENG               
        ) SELECT DT_ARRETE,             
                ID_PARTENAIRE_POOL,    
                CD_SYS_INT,            
                ID_OPERATION,          
                ID_TYPE_POOL,          
                QUOTE_PART_POOL,       
                MNT_VIVANT_FINANCMT,   
                FLAG_CHEF_POOL,        
                SEQ_ID_PARTENAIRE_POOL,
                SEQ_ID_TYPE_POOL,      
                TOP_ENG
        FROM CRR_2A.HIS_BTR_OPE_PARTENAIRE_POOL
        WHERE DT_ARRETE < vDateTransition2A5A;

        -- Purge de la table d'historique 2 ans
        l_position := 'Purge 2 ans';
        DELETE FROM CRR_2A.HIS_BTR_OPE_PARTENAIRE_POOL WHERE DT_ARRETE < vDateTransition2A5A;
        if sql%found then 
            dbms_output.put_line('Purge DELETE CRR_2A.HIS_BTR_OPE_PARTENAIRE_POOL ='|| sql%rowcount ); 
        end if;
        
        -- Purge de la table d'historique 5 ans des donnees vieille de plus de X mois
        l_position := 'Purge CRR_10A';
        DELETE FROM CRR_10A.HIS_BTR_OPE_PARTENAIRE_POOL 
            WHERE DT_ARRETE < vPurge5A;
        if sql%found then 
            dbms_output.put_line('Purge DELETE CRR_10A.HIS_BTR_OPE_PARTENAIRE_POOL ='|| sql%rowcount ); 
        end if;
       
        COMMIT;
        
    EXCEPTION
        WHEN OTHERS THEN 
            ROLLBACK;
            pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM, 'proc p_HIS_BTR_OPE_PARTENAIRE_POOL:'||l_position, 50074);
    END p_HIS_BTR_OPE_PARTENAIRE_POOL;


------------------------------------------------------------------------------------------------------
-- nom : procedure p_his_OPERATION_COVID19                                                          --
-- but : historisation de la table OPERATION_COVID19 dans les schema CRR_2A et CRR_10A              --
-- auteur : KLX_RISQUE (VDC) 02/08/2022                                                             --
-- entree : /                                                                                       --
-- retour : /                                                                                       --
-- Creation pour la Mantis 62593 - Ajout de la table OPERATION_COVID19 , Projet LTBCE               --
------------------------------------------------------------------------------------------------------
    procedure p_his_OPERATION_COVID19 IS 
        -- A terminer
        l_position varchar2(35); -- Etape dans la procedure en cas d'erreur
        vDateTransition2A5A DATE := add_months(g_dt_arrete, -g_nb_mois_purge_2ans);
        vPurge5A DATE := add_months(g_dt_arrete, -g_nb_mois_purge_7ans);
    BEGIN
        l_position := 'REJEU CRR_2A';
        
        --DELETE FROM CRR_2A.HIS_OPERATION_COVID19 WHERE DT_ARRETE = g_dt_arrete;
        DELETE FROM CRR_2A.HIS_OPERATION_COVID19 HOC 
            WHERE EXISTS ( SELECT 1 FROM CRR.OPERATION_COVID19 WHERE ID_OPERATION = HOC.ID_OPERATION AND DT_ARRETE = HOC.DT_ARRETE);

        if sql%found then 
            dbms_output.put_line('rejeu DELETE CRR_2A.HIS_OPERATION_COVID19 ='|| sql%rowcount ); 
        end if;

        l_position := 'Insertion 2A';
        INSERT INTO CRR_2A.HIS_OPERATION_COVID19 (
            DT_ARRETE,
            ID_OPERATION,
            CD_STATUT_MORATOIRE        
        ) SELECT DT_ARRETE,
                ID_OPERATION,
                CD_STATUT_MORATOIRE
        FROM CRR.OPERATION_COVID19;
		-- Mantis67050
		-- Correction pour ï¿½tre sure qu'en cas de reprise, le contenue de CRR_10A.HIS_OPERATION_COVID19 est bien effacer
		-- Avant d'effectuer le passage des donnees d'un sas a un autre efface les donnees deja presentes.
		-- Le CD_STATUT_MORATOIRE n'est pas utiliser actuellement donc possiblement au lieu d'effacer on pourrait faire 
		-- insere si n'existe pas. Cela evite des insertions en double mais cela empeche l'actualisation du cd_statut_moratoire...
		l_position := 'REJEU CRR_10A';
        DELETE FROM CRR_10A.HIS_OPERATION_COVID19 HOC
            WHERE EXISTS ( SELECT 1 FROM CRR_2A.HIS_OPERATION_COVID19 WHERE ID_OPERATION = HOC.ID_OPERATION AND DT_ARRETE = HOC.DT_ARRETE);
        if sql%found then 
            dbms_output.put_line('rejeu DELETE CRR_10A.HIS_OPERATION_COVID19 ='|| sql%rowcount ); 
        end if;
        l_position := 'Insertion 5A';
        INSERT INTO CRR_10A.HIS_OPERATION_COVID19 (
            DT_ARRETE,
            ID_OPERATION,
            CD_STATUT_MORATOIRE        
        ) SELECT DT_ARRETE,
                ID_OPERATION,
                CD_STATUT_MORATOIRE
        FROM CRR_2A.HIS_OPERATION_COVID19
        WHERE DT_ARRETE < vDateTransition2A5A
		--	AND NOT EXISTS ( SELECT 1 FROM CRR_10A.HIS_OPERATION_COVID19 HOC WHERE ID_OPERATION = HOC.ID_OPERATION AND DT_ARRETE = HOC.DT_ARRETE)
		;
			

        -- Purge de la table d'historique 2 ans
        l_position := 'Purge 2 ans';
        DELETE FROM CRR_2A.HIS_OPERATION_COVID19 WHERE DT_ARRETE < vDateTransition2A5A;
        if sql%found then 
            dbms_output.put_line('Purge DELETE CRR_2A.HIS_OPERATION_COVID19 ='|| sql%rowcount ); 
        end if;

        
        
        -- Purge de la table d'historique dans CRR_10A des donnees vieille de plus de X mois
        l_position := 'Purge CRR_10A';
        DELETE FROM CRR_10A.HIS_OPERATION_COVID19 
            WHERE DT_ARRETE < vPurge5A;
        if sql%found then 
            dbms_output.put_line('Purge DELETE CRR_10A.HIS_OPERATION_COVID19 ='|| sql%rowcount ); 
        end if;
        
        COMMIT;
    EXCEPTION
        WHEN OTHERS THEN 
            ROLLBACK;
            pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM, 'proc p_his_OPERATION_COVID19:'||l_position, 50074);
    END p_his_OPERATION_COVID19;

	------------------------------------------------------------------
	-- nom : procedure p_his_PARAM_MULTIDIM_GENERIQUE               --
	-- but : historisation de la table PARAM_MULTIDIM_GENERIQUE     --
	-- auteur : KLX Risque 02/06/2023 Projet LTBCE                  --
	-- entree : /                                                   --
	-- retour : /                                                   --
	------------------------------------------------------------------
	PROCEDURE p_his_PARAM_MULTIDIM_GENERIQUE IS
	    l_position VARCHAR2(20);
	    DT_ARRETE  DATE;
		v_etape    VARCHAR2(100);
	BEGIN
		DT_ARRETE := g_dt_arrete;

        v_etape := 'Effacage si REJEU';
        -- Efface les donnï¿½es marquer au premier de mois
        DELETE HIS_PARAM_MULTIDIM_GENERIQUE 
			WHERE DT_DEBUT_VALIDITE = LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1;
        -- Marque toutes les donnï¿½es  comme ï¿½tant valident jusqu'a la date de l'arrete antï¿½rieur si marquer a la date actuelle
        UPDATE HIS_PARAM_MULTIDIM_GENERIQUE 
            SET DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1)
        WHERE DT_FIN_VALIDITE = DT_ARRETE;

        v_etape := 'INSERT les nouvelles lignes';

        -- INSERT DANS L HISTO SI LA VALEUR EST ABSENTE SUR LE MOIS PRECEDENT UNIQUEMENT
        -- PERMET D HISTORISER MEME SI ON REVIENT A UNE ANCIENNE VALEUR
        INSERT INTO HIS_PARAM_MULTIDIM_GENERIQUE (
			DT_DEBUT_VALIDITE ,
			DT_FIN_VALIDITE ,
			CODE_TYPE_UTILISATION ,
			VAL_TYPE_UTILISATION ,
			CODE_PARAM_1 ,
			VAL_PARAM_1 ,
			CODE_PARAM_2 ,
			VAL_PARAM_2 ,
			CODE_PARAM_3 ,
			VAL_PARAM_3 ,
			CODE_PARAM_4 ,
			VAL_PARAM_4 ,
			CODE_PARAM_5 ,
			VAL_PARAM_5 ,
			CODE_RESULTAT1 ,
			VAL_RESULTAT1 ,
			LIB_RESULTAT1 ,
			CODE_RESULTAT2 ,
			VAL_RESULTAT2 ,
			LIB_RESULTAT2 ,
			CODE_PARAM_6 ,
			VAL_PARAM_6 ,
			CODE_PARAM_7 ,
			VAL_PARAM_7 ,
            CODE_PARAM_8 ,
            VAL_PARAM_8 ,
            CODE_PARAM_9 ,
            VAL_PARAM_9
		)
        SELECT DISTINCT LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1, -- Dï¿½but validitï¿½ = dï¿½but du mois d'arrete
				DT_ARRETE as DT_FIN_VALIDITE,
				CODE_TYPE_UTILISATION ,
				VAL_TYPE_UTILISATION ,
				CODE_PARAM_1 ,
				VAL_PARAM_1 ,
				CODE_PARAM_2 ,
				VAL_PARAM_2 ,
				CODE_PARAM_3 ,
				VAL_PARAM_3 ,
				CODE_PARAM_4 ,
				VAL_PARAM_4 ,
				CODE_PARAM_5 ,
				VAL_PARAM_5 ,
				CODE_RESULTAT1 ,
				VAL_RESULTAT1 ,
				LIB_RESULTAT1 ,
				CODE_RESULTAT2 ,
				VAL_RESULTAT2 ,
				LIB_RESULTAT2 ,
				CODE_PARAM_6 ,
				VAL_PARAM_6 ,
				CODE_PARAM_7 ,
				VAL_PARAM_7 ,
                CODE_PARAM_8 ,
                VAL_PARAM_8 ,
                CODE_PARAM_9 ,
                VAL_PARAM_9
        FROM PARAM_MULTIDIM_GENERIQUE PARAM -- M69678 - Ajout de COALESCE pour comparer avec les NULL
        WHERE NOT EXISTS (  SELECT 1 FROM HIS_PARAM_MULTIDIM_GENERIQUE his_param -- Si on a pas la mï¿½me ligne au mois dernier alors on historise
                             WHERE COALESCE(his_param.CODE_TYPE_UTILISATION, 'NULL') = COALESCE(PARAM.CODE_TYPE_UTILISATION, 'NULL')
							   AND COALESCE(his_param.VAL_TYPE_UTILISATION, 'NULL')  = COALESCE(PARAM.VAL_TYPE_UTILISATION, 'NULL')
							   AND COALESCE(his_param.CODE_PARAM_1, 'NULL')          = COALESCE(PARAM.CODE_PARAM_1, 'NULL')
							   AND COALESCE(his_param.VAL_PARAM_1, 'NULL')           = COALESCE(PARAM.VAL_PARAM_1, 'NULL')
							   AND COALESCE(his_param.CODE_PARAM_2, 'NULL')          = COALESCE(PARAM.CODE_PARAM_2, 'NULL')
							   AND COALESCE(his_param.VAL_PARAM_2, 'NULL')           = COALESCE(PARAM.VAL_PARAM_2, 'NULL')
							   AND COALESCE(his_param.CODE_PARAM_3, 'NULL')          = COALESCE(PARAM.CODE_PARAM_3, 'NULL')
						  	   AND COALESCE(his_param.VAL_PARAM_3, 'NULL')           = COALESCE(PARAM.VAL_PARAM_3, 'NULL')
							   AND COALESCE(his_param.CODE_PARAM_4, 'NULL')          = COALESCE(PARAM.CODE_PARAM_4, 'NULL')
							   AND COALESCE(his_param.VAL_PARAM_4, 'NULL')           = COALESCE(PARAM.VAL_PARAM_4, 'NULL')
						 	   AND COALESCE(his_param.CODE_PARAM_5, 'NULL')          = COALESCE(PARAM.CODE_PARAM_5, 'NULL')
							   AND COALESCE(his_param.VAL_PARAM_5, 'NULL')           = COALESCE(PARAM.VAL_PARAM_5, 'NULL')
							   AND COALESCE(his_param.CODE_RESULTAT1, 'NULL')        = COALESCE(PARAM.CODE_RESULTAT1, 'NULL')
							   AND COALESCE(his_param.VAL_RESULTAT1, 'NULL')         = COALESCE(PARAM.VAL_RESULTAT1, 'NULL')
							   AND COALESCE(his_param.LIB_RESULTAT1, 'NULL')         = COALESCE(PARAM.LIB_RESULTAT1, 'NULL')
							   AND COALESCE(his_param.CODE_RESULTAT2, 'NULL')        = COALESCE(PARAM.CODE_RESULTAT2, 'NULL')
							   AND COALESCE(his_param.VAL_RESULTAT2, 'NULL')         = COALESCE(PARAM.VAL_RESULTAT2, 'NULL')
							   AND COALESCE(his_param.LIB_RESULTAT2, 'NULL')         = COALESCE(PARAM.LIB_RESULTAT2, 'NULL')
							   AND COALESCE(his_param.CODE_PARAM_6, 'NULL')          = COALESCE(PARAM.CODE_PARAM_6, 'NULL')
							   AND COALESCE(his_param.VAL_PARAM_6, 'NULL')           = COALESCE(PARAM.VAL_PARAM_6, 'NULL')
							   AND COALESCE(his_param.CODE_PARAM_7, 'NULL')          = COALESCE(PARAM.CODE_PARAM_7, 'NULL')
							   AND COALESCE(his_param.VAL_PARAM_7, 'NULL')           = COALESCE(PARAM.VAL_PARAM_7, 'NULL')
                               AND COALESCE(his_param.CODE_PARAM_8, 'NULL')          = COALESCE(PARAM.CODE_PARAM_8, 'NULL')
                               AND COALESCE(his_param.VAL_PARAM_8, 'NULL')           = COALESCE(PARAM.VAL_PARAM_8, 'NULL')
                               AND COALESCE(his_param.CODE_PARAM_9, 'NULL')          = COALESCE(PARAM.CODE_PARAM_9, 'NULL')
                               AND COALESCE(his_param.VAL_PARAM_9, 'NULL')           = COALESCE(PARAM.VAL_PARAM_9, 'NULL')
                               AND his_param.DT_FIN_VALIDITE                         = ADD_MONTHS(DT_ARRETE, -1)
                        );
        -- ADD_MONTHS(DT_ARRETE, -1) => Si la DT_ARRETE est le dernier jour du mois, ADD_MONTHS(DT_ARRETE, -1) donnera le dernier jour du mois antï¿½rieur
        v_etape := 'UPDATE';
        -- ON UPDATE UNIQUEMENT LES VALEURS ACTUELLES SUR LE DERNIER HISTORIQUE
        -- SI ON REVIENT A UNE ANCIENNE VALEUR, L ANCIENNE VALEUR N EST PAS UPDATEE
        -- SI UNE VALEUR N EST PLUS PRESENTE, ON NE CHANGE PAS SA DATE
        UPDATE HIS_PARAM_MULTIDIM_GENERIQUE his_param
        SET DT_FIN_VALIDITE = DT_ARRETE -- M69678 - Ajout de COALESCE pour comparer avec les NULL
        WHERE EXISTS (  SELECT 1 FROM PARAM_MULTIDIM_GENERIQUE param
						 WHERE COALESCE(PARAM.CODE_TYPE_UTILISATION, 'NULL') = COALESCE( his_param.CODE_TYPE_UTILISATION, 'NULL')
						   AND COALESCE(PARAM.VAL_TYPE_UTILISATION, 'NULL')  = COALESCE( his_param.VAL_TYPE_UTILISATION, 'NULL')
						   AND COALESCE(PARAM.CODE_PARAM_1, 'NULL')          = COALESCE( his_param.CODE_PARAM_1, 'NULL')
						   AND COALESCE(PARAM.VAL_PARAM_1, 'NULL')           = COALESCE( his_param.VAL_PARAM_1, 'NULL')
						   AND COALESCE(PARAM.CODE_PARAM_2, 'NULL')          = COALESCE( his_param.CODE_PARAM_2, 'NULL')
						   AND COALESCE(PARAM.VAL_PARAM_2, 'NULL')           = COALESCE( his_param.VAL_PARAM_2, 'NULL')
						   AND COALESCE(PARAM.CODE_PARAM_3, 'NULL')          = COALESCE( his_param.CODE_PARAM_3, 'NULL')
						   AND COALESCE(PARAM.VAL_PARAM_3, 'NULL')           = COALESCE( his_param.VAL_PARAM_3, 'NULL')
						   AND COALESCE(PARAM.CODE_PARAM_4, 'NULL')          = COALESCE( his_param.CODE_PARAM_4, 'NULL')
						   AND COALESCE(PARAM.VAL_PARAM_4, 'NULL')           = COALESCE( his_param.VAL_PARAM_4, 'NULL')
						   AND COALESCE(PARAM.CODE_PARAM_5, 'NULL')          = COALESCE( his_param.CODE_PARAM_5, 'NULL')
						   AND COALESCE(PARAM.VAL_PARAM_5, 'NULL')           = COALESCE( his_param.VAL_PARAM_5, 'NULL')
						   AND COALESCE(PARAM.CODE_RESULTAT1, 'NULL')        = COALESCE( his_param.CODE_RESULTAT1, 'NULL')
						   AND COALESCE(PARAM.VAL_RESULTAT1, 'NULL')         = COALESCE( his_param.VAL_RESULTAT1, 'NULL')
						   AND COALESCE(PARAM.LIB_RESULTAT1, 'NULL')         = COALESCE( his_param.LIB_RESULTAT1, 'NULL')
						   AND COALESCE(PARAM.CODE_RESULTAT2, 'NULL')        = COALESCE( his_param.CODE_RESULTAT2, 'NULL')
						   AND COALESCE(PARAM.VAL_RESULTAT2, 'NULL')         = COALESCE( his_param.VAL_RESULTAT2, 'NULL')
						   AND COALESCE(PARAM.LIB_RESULTAT2, 'NULL')         = COALESCE( his_param.LIB_RESULTAT2, 'NULL')
						   AND COALESCE(PARAM.CODE_PARAM_6, 'NULL')          = COALESCE( his_param.CODE_PARAM_6, 'NULL')
						   AND COALESCE(PARAM.VAL_PARAM_6, 'NULL')           = COALESCE( his_param.VAL_PARAM_6, 'NULL')
						   AND COALESCE(PARAM.CODE_PARAM_7, 'NULL')          = COALESCE( his_param.CODE_PARAM_7, 'NULL')
						   AND COALESCE(PARAM.VAL_PARAM_7, 'NULL')           = COALESCE( his_param.VAL_PARAM_7, 'NULL')
						   AND COALESCE(PARAM.CODE_PARAM_8, 'NULL')          = COALESCE( his_param.CODE_PARAM_8, 'NULL')
						   AND COALESCE(PARAM.VAL_PARAM_8, 'NULL')           = COALESCE( his_param.VAL_PARAM_8, 'NULL')
						   AND COALESCE(PARAM.CODE_PARAM_9, 'NULL')          = COALESCE( his_param.CODE_PARAM_9, 'NULL')
						   AND COALESCE(PARAM.VAL_PARAM_9, 'NULL')           = COALESCE( his_param.VAL_PARAM_9, 'NULL')
                        )
        AND his_param.DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1);
        COMMIT;
	EXCEPTION
	    WHEN OTHERS THEN
	             ROLLBACK;
	              pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'proc p_his_PARAM_MULTIDIM_GENERIQUE:'||l_position,50076);
	END p_his_PARAM_MULTIDIM_GENERIQUE;

