-- =================================================================================
-- 	procedure      : p_histo_BTR_GRILLE_CBRE
--  description    : historisation dans la table HIS_BTR_GRILLE_CBRE
--	auteur		   : Bruno Almeida (KLx_Risques)
--  params. entree : NA
--  params. retour : NA
--  date creation  : 19/04/2023
--  dern. modif.   : dd/mm/yyyy
--  historique     : Project VTR-CBI :: sous-chapitre 4.3.3
-- =================================================================================
    procedure p_histo_BTR_GRILLE_CBRE is
		--variables locales
		pEtape       varchar2(250);
		pDt_Arrete   date;
        pDern_Dt_2A  date;
        pDern_Dt_5A  date;

    begin
        --initialisation des variables
        pDt_Arrete 	:= pack_utilitaire_7ans.f_calc_dt_arrete;
        pDern_Dt_2A := add_months(pDt_Arrete, -g_nb_mois_purge_2ans);
        pDern_Dt_5A := add_months(pDt_Arrete, -g_nb_mois_purge_7ans);
		
		--rejeu pour eviter doublons
        pEtape := 'Rejeu HIS_BTR_GRILLE_CBRE';
        delete 
		  from CRR.his_btr_grille_cbre 
		 where dt_debut_effet = pDt_Arrete;
        commit;
		
		pEtape := 'Historisation HIS_BTR_GRILLE_CBRE';
        insert 
        into CRR.his_btr_grille_cbre 
          (cd_famille_imm
          ,cd_sit_geo_n1
		  ,cd_sit_geo_n2
		  ,cd_type_copropriete
		  ,cd_anciennete_actif
		  ,cd_categ_complementaire
		  ,tx_ponderation_vtr
		  ,n_valeur_locative
		  ,tx_capitalisation
		  ,dt_debut_effet) 
        select 
           cd_famille_imm
          ,cd_sit_geo_n1
		  ,cd_sit_geo_n2
		  ,cd_type_copropriete
		  ,cd_anciennete_actif
		  ,cd_categ_complementaire
		  ,tx_ponderation_vtr
		  ,n_valeur_locative
		  ,tx_capitalisation
		  ,dt_debut_effet
        from CRR.btr_grille_cbre;
        commit;
		
		pEtape := 'Historisation HIS_BTR_GRILLE_CBRE :: 2 ans';
        delete 
		  from CRR_2A.his_btr_grille_cbre 
		 where dt_debut_effet = pDt_Arrete;

        insert into CRR_2A.his_btr_grille_cbre
		select * 
		  from CRR.his_btr_grille_cbre 
		 where dt_debut_effet = pDt_Arrete;
		commit;

		pEtape := 'Purge des donnees HIS_BTR_GRILLE_CBRE :: 2 ans';
		delete 
		  from CRR_2A.his_btr_grille_cbre 
		 where dt_debut_effet < pDern_Dt_2A;
		commit;
		
		pEtape := 'Historisation HIS_BTR_GRILLE_CBRE :: 5 ans';
        delete 
		  from CRR_10A.his_btr_grille_cbre 
		 where dt_debut_effet = pDt_Arrete;

		insert into CRR_10A.his_btr_grille_cbre
		select * 
		  from CRR.his_btr_grille_cbre 
		 where dt_debut_effet = pDt_Arrete;
		commit;
		
		pEtape := 'Purge des donnees HIS_BTR_GRILLE_CBRE :: 5 ans';
		delete 
		  from CRR_10A.his_btr_grille_cbre 
		 where dt_debut_effet >= pDern_Dt_2A 
		    or dt_debut_effet < pDern_Dt_5A;
		commit;
    exception 
    when others then
        rollback;
        pack_utilitaire_7ans.db_traite_erreur(sqlerrm, 'Procedure: p_histo_BTR_GRILLE_CBRE :: Etape: ' || pEtape, 50074);
    end p_histo_BTR_GRILLE_CBRE;
-- =================================================================================
-- 	FIN procedure : p_histo_BTR_GRILLE_CBRE
-- =================================================================================

