-- BEGIN p_histo_RS_STATUT_MORATOIRE

PROCEDURE p_histo_RS_STATUT_MORATOIRE IS
    l_position varchar2(20);
    DT_ARRETE DATE;
BEGIN
	DT_ARRETE := g_dt_arrete;
	L_POSITION := 'SI REJEU';

	DELETE HIS_RS_STATUT_MORATOIRE WHERE DT_DEBUT_VALIDITE = LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1;

	UPDATE HIS_RS_STATUT_MORATOIRE SET DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1)
	WHERE DT_FIN_VALIDITE = DT_ARRETE;

	L_POSITION := 'INSERT';

	-- INSERT DANS L HISTO SI LA VALEUR EST ABSENTE SUR LE MOIS PRECEDENT UNIQUEMENT
	-- PERMET D HISTORISER MEME SI ON REVIENT A UNE ANCIENNE VALEUR
	INSERT INTO HIS_RS_STATUT_MORATOIRE  (
		 STATUT_MRTR
		,LIB_STATUT_MRTR
		,DT_DEBUT_VALIDITE
		,DT_FIN_VALIDITE
	) 
	SELECT
		 STATUT_MRTR
		,LIB_STATUT_MRTR
		,LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1
		,DT_ARRETE
    FROM RS_STATUT_MORATOIRE rs
    WHERE NOT EXISTS (SELECT 1
						FROM  HIS_RS_STATUT_MORATOIRE his_rs
						WHERE his_rs.STATUT_MRTR 		= rs.STATUT_MRTR
						AND   his_rs.LIB_STATUT_MRTR 	= rs.LIB_STATUT_MRTR
						AND   his_rs.DT_FIN_VALIDITE 	= ADD_MONTHS(DT_ARRETE, -1));

	L_POSITION := 'UPDATE';

	-- ON UPDATE UNIQUEMENT LES VALEURS ACTUELLES SUR LE DERNIER HISTORIQUE
	-- SI ON REVIENT A UNE ANCIENNE VALEUR, L ANCIENNE VALEUR N EST PAS UPDATEE
	-- SI UNE VALEUR N EST PLUS PRESENTE, ON NE CHANGE PAS SA DATE
	UPDATE HIS_RS_STATUT_MORATOIRE his_rs
	SET DT_FIN_VALIDITE = DT_ARRETE
	WHERE EXISTS (SELECT 1
					FROM  RS_STATUT_MORATOIRE rs
					WHERE his_rs.STATUT_MRTR 		= rs.STATUT_MRTR
					AND   his_rs.LIB_STATUT_MRTR 	= rs.LIB_STATUT_MRTR)
	AND his_rs.DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1);

	COMMIT;

EXCEPTION
	WHEN OTHERS THEN
		ROLLBACK;
			pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'p_histo_RS_STATUT_MORATOIRE:'||l_position,50074);

END  p_histo_RS_STATUT_MORATOIRE;

-- END p_histo_RS_STATUT_MORATOIRE
------------------------------------------


