PROCEDURE p_histo_REF_CORRES_FORM_JUR_FIFI243 IS
    l_position varchar2(20);
    DT_ARRETE DATE;

BEGIN
	DT_ARRETE := g_dt_arrete;

	L_POSITION := 'SI REJEU';

DELETE HIS_REF_CORRES_FORM_JUR_FIFI243 WHERE DT_DEBUT_VALIDITE = LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1;

	UPDATE HIS_REF_CORRES_FORM_JUR_FIFI243 SET DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1)
	WHERE DT_FIN_VALIDITE = DT_ARRETE;

	L_POSITION := 'INSERT';

	-- INSERT DANS L HISTO SI LA VALEUR EST ABSENTE SUR LE MOIS PRECEDENT UNIQUEMENT
	-- PERMET D HISTORISER MEME SI ON REVIENT A UNE ANCIENNE VALEUR
	INSERT INTO HIS_REF_CORRES_FORM_JUR_FIFI243 (
		CD_FORM_JUR
       ,IND_NATURE_DURABLE
	   ,DT_DEBUT_VALIDITE
	   ,DT_FIN_VALIDITE
	)
	SELECT
		 CD_FORM_JUR
        ,IND_NATURE_DURABLE
		,LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1
		,DT_ARRETE
    FROM REF_CORRES_FORM_JUR_FIFI243 rs
   WHERE NOT EXISTS (SELECT 1
					   FROM HIS_REF_CORRES_FORM_JUR_FIFI243 his_rs
					  WHERE his_rs.CD_FORM_JUR 	      = rs.CD_FORM_JUR
						AND his_rs.IND_NATURE_DURABLE = rs.IND_NATURE_DURABLE
						AND his_rs.DT_FIN_VALIDITE	  = ADD_MONTHS(DT_ARRETE, -1));

	L_POSITION := 'UPDATE';

	-- ON UPDATE UNIQUEMENT LES VALEURS ACTUELLES SUR LE DERNIER HISTORIQUE
	-- SI ON REVIENT A UNE ANCIENNE VALEUR, L ANCIENNE VALEUR N EST PAS UPDATEE
	-- SI UNE VALEUR N EST PLUS PRESENTE, ON NE CHANGE PAS SA DATE
	UPDATE HIS_REF_CORRES_FORM_JUR_FIFI243 his_rs
	SET DT_FIN_VALIDITE = DT_ARRETE
	WHERE EXISTS (SELECT 1
					FROM REF_CORRES_FORM_JUR_FIFI243 rs
				  WHERE his_rs.CD_FORM_JUR 	      = rs.CD_FORM_JUR
					AND his_rs.IND_NATURE_DURABLE = rs.IND_NATURE_DURABLE)
	AND his_rs.DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1);

	COMMIT;

EXCEPTION
	WHEN OTHERS THEN
		ROLLBACK;
			pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'p_histo_REF_CORRES_FORM_JUR_FIFI243:'||l_position,50074);

END p_histo_REF_CORRES_FORM_JUR_FIFI243;

