PROCEDURE p_histo_REF_CATEG_BIEN IS
    l_position varchar2(20);
    DT_ARRETE DATE;

BEGIN
	DT_ARRETE := g_dt_arrete;

	L_POSITION := 'SI REJEU';

DELETE HIS_REF_CATEG_BIEN WHERE DT_DEBUT_VALIDITE = LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1;

	UPDATE HIS_REF_CATEG_BIEN SET DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1)
	WHERE DT_FIN_VALIDITE = DT_ARRETE;

	L_POSITION := 'INSERT';

	-- INSERT DANS L HISTO SI LA VALEUR EST ABSENTE SUR LE MOIS PRECEDENT UNIQUEMENT
	-- PERMET D HISTORISER MEME SI ON REVIENT A UNE ANCIENNE VALEUR
	INSERT INTO HIS_REF_CATEG_BIEN (
		CD_FAMILLE_IMM
	   ,LIB_FAMILLE_IMM
	   ,CD_TYPO_COMMERCE
	   ,LIB_TYPOLOGIE_COMMERCE
	   ,CD_TYPO_ENTREPOT
	   ,CD_CATEG_BIEN
	   ,DT_DEBUT_VALIDITE
	   ,DT_FIN_VALIDITE
	)
	SELECT
		 CD_FAMILLE_IMM
		,LIB_FAMILLE_IMM
		,CD_TYPO_COMMERCE
		,LIB_TYPOLOGIE_COMMERCE
		,CD_TYPO_ENTREPOT
		,CD_CATEG_BIEN
		,LAST_DAY(ADD_MONTHS(DT_ARRETE, -1))+1
		,DT_ARRETE
    FROM REF_CATEG_BIEN rs
   WHERE NOT EXISTS (SELECT 1
					   FROM HIS_REF_CATEG_BIEN his_rs
					  WHERE his_rs.CD_FAMILLE_IMM 	      = rs.CD_FAMILLE_IMM
						AND his_rs.LIB_FAMILLE_IMM        = rs.LIB_FAMILLE_IMM
						AND his_rs.CD_TYPO_COMMERCE       = rs.CD_TYPO_COMMERCE
						AND his_rs.LIB_TYPOLOGIE_COMMERCE = rs.LIB_TYPOLOGIE_COMMERCE
						AND his_rs.CD_TYPO_ENTREPOT       = rs.CD_TYPO_ENTREPOT
						AND his_rs.CD_CATEG_BIEN          = rs.CD_CATEG_BIEN
						AND his_rs.DT_FIN_VALIDITE	      = ADD_MONTHS(DT_ARRETE, -1));

	L_POSITION := 'UPDATE';

	-- ON UPDATE UNIQUEMENT LES VALEURS ACTUELLES SUR LE DERNIER HISTORIQUE
	-- SI ON REVIENT A UNE ANCIENNE VALEUR, L ANCIENNE VALEUR N EST PAS UPDATEE
	-- SI UNE VALEUR N EST PLUS PRESENTE, ON NE CHANGE PAS SA DATE
	UPDATE HIS_REF_CATEG_BIEN his_rs
	SET DT_FIN_VALIDITE = DT_ARRETE
	WHERE EXISTS (SELECT 1
					FROM REF_CATEG_BIEN rs
				  WHERE his_rs.CD_FAMILLE_IMM 	      = rs.CD_FAMILLE_IMM
					AND his_rs.LIB_FAMILLE_IMM        = rs.LIB_FAMILLE_IMM
					AND his_rs.CD_TYPO_COMMERCE       = rs.CD_TYPO_COMMERCE
					AND his_rs.LIB_TYPOLOGIE_COMMERCE = rs.LIB_TYPOLOGIE_COMMERCE
					AND his_rs.CD_TYPO_ENTREPOT       = rs.CD_TYPO_ENTREPOT
					AND his_rs.CD_CATEG_BIEN          = rs.CD_CATEG_BIEN)
	AND his_rs.DT_FIN_VALIDITE = ADD_MONTHS(DT_ARRETE, -1);

	COMMIT;

EXCEPTION
	WHEN OTHERS THEN
		ROLLBACK;
			pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'p_histo_REF_CATEG_BIEN:'||l_position,50074);

END p_histo_REF_CATEG_BIEN;

