    -- =================================================================================
    -- 	procedure      : p_histo_RS_IND_WATCH_LIST
    --  description    : projet FED: historisation des indicateurs watchlist
    --	auteur		   : Bruno Almeida (KLx_Risques)
    --  params. entree : NA
    --  params. retour : NA
    --  date creation  : 11/11/2025
    --  dern. modif.   : dd/mm/yyyy
    --  historique     : SIRL-606
    -- =================================================================================
    PROCEDURE p_histo_RS_IND_WATCH_LIST IS
        -- variables locales
        l_position varchar2(150);
        dt_arrete  date;
    BEGIN
        -- initialisation des valeurs
        dt_arrete := g_dt_arrete;

        l_position := 'Rejeu - HIS_RS_IND_WATCH_LIST';
        DELETE his_rs_ind_watch_list
         WHERE dt_debut_validite = last_day(add_months(dt_arrete,-1)) + 1;

        UPDATE his_rs_ind_watch_list
           SET dt_fin_validite = add_months(dt_arrete,-1)
         WHERE dt_fin_validite = dt_arrete;

        l_position := 'Insert - HIS_RS_IND_WATCH_LIST';
        INSERT
          INTO his_rs_ind_watch_list (code, libelle_fr, libelle_en, dt_debut_validite, dt_fin_validite)
        SELECT code
             , libelle_fr
             , libelle_en
             , last_day(add_months(dt_arrete,-1)) + 1
             , dt_arrete
          FROM rs_ind_watch_list rs
         WHERE
           NOT
        EXISTS (select 1
                  from his_rs_ind_watch_list his
                 where his.code            = rs.code
                   and his.libelle_fr      = rs.libelle_fr
                   and his.libelle_en      = rs.libelle_en
                   and his.dt_fin_validite = add_months(dt_arrete,-1));

        l_position := 'Update - HIS_RS_IND_WATCH_LIST';
        UPDATE his_rs_ind_watch_list his
           SET his.dt_fin_validite = dt_arrete
         WHERE
        EXISTS (select 1
                  from rs_ind_watch_list rs
                 where rs.code             = his.code
                   and rs.libelle_fr       = his.libelle_fr
                   and rs.libelle_en       = his.libelle_en)
           AND his.dt_fin_validite = add_months(dt_arrete,-1);
        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'Procedure: p_histo_RS_IND_WATCH_LIST - Etape: ' || l_position, 50074);
    END p_histo_RS_IND_WATCH_LIST;

    -- =================================================================================
    -- 	procedure      : p_histo_RS_WL_MOTIF
    --  description    : projet FED: historisation des motifs d'entree et sortie
    --	auteur		   : Bruno Almeida (KLx_Risques)
    --  params. entree : NA
    --  params. retour : NA
    --  date creation  : 11/11/2025
    --  dern. modif.   : dd/mm/yyyy
    --  historique     : SIRL-606
    -- =================================================================================
    PROCEDURE p_histo_RS_WL_MOTIF IS
        -- variables locales
        l_position varchar2(150);
        dt_arrete  date;
    BEGIN
        -- initialisation des valeurs
        dt_arrete := g_dt_arrete;

        l_position := 'Rejeu - HIS_RS_WL_MOTIF';
        DELETE his_rs_wl_motif
         WHERE dt_debut_validite = last_day(add_months(dt_arrete,-1)) + 1;

        UPDATE his_rs_wl_motif
           SET dt_fin_validite = add_months(dt_arrete,-1)
         WHERE dt_fin_validite = dt_arrete;

        l_position := 'Insert - HIS_RS_WL_MOTIF';
        INSERT
          INTO his_rs_wl_motif (code, libelle_fr, libelle_en, cd_ind_entree_sortie, cd_type_wl_casa, dt_debut_validite, dt_fin_validite)
        SELECT code
             , libelle_fr
             , libelle_en
             , cd_ind_entree_sortie
             , cd_type_wl_casa
             , last_day(add_months(dt_arrete,-1)) + 1
             , dt_arrete
          FROM rs_wl_motif rs
         WHERE
           NOT
        EXISTS (select 1
                  from his_rs_wl_motif his
                 where his.code                 = rs.code
                   and his.libelle_fr           = rs.libelle_fr
                   and his.libelle_en           = rs.libelle_en
                   and his.cd_ind_entree_sortie = rs.cd_ind_entree_sortie
                   and his.cd_type_wl_casa      = rs.cd_type_wl_casa
                   and his.dt_fin_validite      = add_months(dt_arrete,-1));

        l_position := 'Update - HIS_RS_WL_MOTIF';
        UPDATE his_rs_wl_motif his
           SET his.dt_fin_validite = dt_arrete
         WHERE
        EXISTS (select 1
                  from rs_wl_motif rs
                 where rs.code                 = his.code
                   and rs.libelle_fr           = his.libelle_fr
                   and rs.libelle_en           = his.libelle_en
                   and rs.cd_ind_entree_sortie = his.cd_ind_entree_sortie
                   and rs.cd_type_wl_casa      = his.cd_type_wl_casa)
           AND his.dt_fin_validite = add_months(dt_arrete,-1);
        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            pack_utilitaire_7ans.DB_TRAITE_ERREUR(SQLERRM,'Procedure: p_histo_RS_WL_MOTIF - Etape: ' || l_position, 50074);
    END p_histo_RS_WL_MOTIF;

